    ru: { 1:"Инициатива, смелость и дух первопроходца. Рождённые под 1 открывают пути и вдохновляют других.", 2:"Дипломатия, сотрудничество и чуткость. 2 объединяет людей и гармонизирует среду.", 3:"Выражение, общение и оптимизм. 3 превращает идеи в искусство и вдохновляет словом.", 4:"Организация, дисциплина и безопасность. 4 строит прочные и долговечные основы.", 5:"Приключение, адаптивность и универсальность. 5 любит перемены и живёт в движении.", 6:"Любовь, ответственность и забота. 6 защищает семью и взращивает красоту.", 7:"Интроспекция, мудрость и духовность. 7 ищет глубокие знания.", 8:"Достижение, авторитет и изобилие. 8 с решимостью владеет материальным миром.", 9:"Сострадание, завершение и гуманизм. 9 закрывает циклы и служит целому." },
